<script setup lang="ts">
import { reactive,watch,computed,nextTick,onMounted,onUnmounted } from 'vue';
import { X,FolderOpen,ArrowUp,ChevronRight,RefreshCw,AlertTriangle,Check,Server,Play,Square } from '@lucide/vue';
import { desk,safely,request,operation,apiPath,refresh,loadProject,applyPreset,removeSelected,makeDirectory,restoreConfirm,browse,openBrowse,serverImport,service,notify,resetProjectNavigation } from './store';
import { bytes,presets,type Data } from './model';
const form=reactive<Data>({});
const repairVersions=computed(()=>desk.releaseFiles.find(file=>file.path===form.path)?.versions||[]);
const title=computed(()=>({ 'project-create':'创建项目',directory:'新建文件夹','preset-confirm':'确认维护方式',remove:'移出所选内容',group:'可选内容','group-members':'加入可选内容',restore:'恢复设置与文件',correct:'修复玩家副本',rollback:'创建回滚发布','problem-confirm':'处理历史坏版本',browse:'选择服务器路径','import-server':'从服务器导入',service:'下载服务','file-actions':'所选内容'} as Record<string,string>)[desk.dialog]||'操作');
watch(()=>desk.dialog,()=>{for(const k of Object.keys(form))delete form[k];if(desk.dialog==='project-create')Object.assign(form,{id:`modpack-${(desk.state.projects?.length||0)+1}`,displayName:'',sourceDirectory:'',publicBaseUrl:''});if(desk.dialog==='group')Object.assign(form,{id:'',title:'',description:'',defaultInstall:true});Object.assign(form,desk.dialogData);if(desk.dialog==='remove')form.action='DELETE';});
async function submit(){if(['problem-confirm','correct'].includes(desk.dialog)&&!String(form.reason||'').trim())throw new Error('请填写处理原因，玩家会看到这条说明');await operation(async()=>{
 switch(desk.dialog){
 case 'project-create':{if(desk.uploading||desk.tasks.some(t=>t.state!=='done'))throw new Error('请先完成或移出导入清单，再创建项目');const project=await request('/api/projects','POST',form);desk.projectId=project.id;resetProjectNavigation();await refresh();desk.view='files';desk.settingsDirty=false;break;}
 case 'group':await request(apiPath('/maintenance/group'),'POST',form);await loadProject();notify('可选内容已保存');break;
 case 'group-members':await request(apiPath('/maintenance/group-members'),'POST',{groupId:form.groupId,items:desk.selection.map(e=>({path:e.path,directory:e.directory,modId:e.componentId})),add:true});await loadProject();break;
 case 'rollback':await request(apiPath('/rollback'),'POST',{targetReleaseId:form.release.releaseId,displayVersion:form.version,changelog:form.notes,acknowledgePlayerUpgrade:form.ack});await refresh();notify('回滚版本已发布');break;
 case 'problem-confirm':await request(apiPath('/maintenance/withdraw'),'POST',{reason:form.reason,versions:form.versions});await loadProject();notify('问题处理已保存，检查并发布后生效');break;
 case 'correct':await request(apiPath('/maintenance/correct'),'POST',{path:form.path,mode:form.mode,reason:form.reason,badSha256:form.badSha256});await loadProject();notify('修复要求已保存，检查并发布后生效');break;
 }
 desk.dialog='';
 },'正在保存…');}
async function browseConfirm(){const path=desk.browseSelected||desk.browse.path||desk.browsePath;if(desk.browseAction==='import'){const entry=desk.browse.entries?.find((e:Data)=>e.path===path);if(!entry?.regularFile)throw new Error('请选择一个文件');await serverImport(path);}else if(desk.dialogData.returnDialog){const action=desk.browseAction;desk.dialogData={...desk.dialogData,[action]:path};desk.dialog=desk.dialogData.returnDialog;}else{desk.browseValues[desk.browseAction]=path;desk.dialog='';}}
function close(){if(!desk.busy)desk.dialog='';}
let priorFocus:HTMLElement|null=null;
watch(()=>desk.dialog,(value,previous)=>{if(value&&!previous)priorFocus=document.activeElement as HTMLElement;void nextTick(()=>{if(value)document.querySelector<HTMLElement>('.native-dialog input:not([type=radio],[type=checkbox]),.native-dialog select,.native-dialog button')?.focus();else priorFocus?.focus();});});
function trap(event:KeyboardEvent){if(!desk.dialog)return;if(event.key==='Escape'){event.preventDefault();close();}if(event.key==='Tab'){const nodes=[...document.querySelectorAll<HTMLElement>('.native-dialog button:not(:disabled),.native-dialog input:not(:disabled),.native-dialog select:not(:disabled),.native-dialog textarea:not(:disabled),.native-dialog summary')].filter(e=>e.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}}
onMounted(()=>window.addEventListener('keydown',trap));onUnmounted(()=>window.removeEventListener('keydown',trap));
</script>
<template>
 <div v-if="desk.dialog" class="modal-backdrop" @click.self="close"><section class="native-dialog" :class="{wide:desk.dialog==='browse'||desk.dialog==='restore'}" role="dialog" aria-modal="true" :aria-label="title"><header><h2>{{title}}</h2><button class="icon-button" aria-label="关闭弹窗" :disabled="desk.busy" @click="close"><X :size="18"/></button></header>
  <form v-if="desk.dialog==='project-create'" @submit.prevent="safely(submit)"><label>项目名称<input v-model="form.displayName" placeholder="例如 我的整合包" required></label><label>项目 ID<input v-model="form.id" pattern="[A-Za-z0-9][A-Za-z0-9._-]*" required><small>用于更新地址，创建后保持不变。</small></label><label>整合包目录<div class="field-with-button"><input v-model="form.sourceDirectory" placeholder="存放 mods、config 的目录" required><button type="button" @click="desk.dialogData={...form,returnDialog:'project-create'};openBrowse('directory','sourceDirectory',form.sourceDirectory)"><FolderOpen :size="16"/></button></div></label><label>玩家更新地址<input v-model="form.publicBaseUrl" type="url" placeholder="https://updates.example.com/" required></label><footer><button type="button" @click="close">取消</button><button class="accent" :disabled="desk.busy">创建项目</button></footer></form>
  <form v-else-if="desk.dialog==='directory'" @submit.prevent="safely(()=>makeDirectory(form.path))"><label>目录路径<input v-model="form.path" required></label><footer><button type="button" @click="close">取消</button><button class="accent">创建文件夹</button></footer></form>
  <div v-else-if="desk.dialog==='preset-confirm'"><p>所选 {{desk.selection.length}} 项内容将使用下方维护方式。文件夹内的文件会一起应用。</p><label>维护方式<select v-model="form.preset"><option value="SYNC">普通同步</option><option value="REQUIRED">强制同步</option><option value="INITIAL">首次提供</option></select></label><p class="dialog-note">{{presets[form.preset]?.description}}</p><div class="selection-summary" v-for="entry in desk.selection" :key="entry.path"><img :src="entry.directory?'/icons/folder.svg':'/icons/file.svg'" alt=""><span>{{entry.path}}</span></div><footer><button @click="close">取消</button><button class="accent" :disabled="desk.busy" @click="safely(async()=>{await applyPreset(form.preset);desk.dialog='';})">确认修改</button></footer></div>
  <div v-else-if="desk.dialog==='remove'"><p>所选内容会先归档，再移出整合包目录。发布后，按下方方式处理玩家副本。</p><label class="choice-row"><input v-model="form.action" type="radio" value="DELETE"><div><strong>移除玩家副本</strong><small>之后装回的匹配副本也会先备份，再移出。</small></div></label><label class="choice-row"><input v-model="form.action" type="radio" value="RELEASE"><div><strong>停止维护，留给玩家</strong><small>玩家已有内容留在原处，之后由玩家管理。</small></div></label><footer><button @click="close">取消</button><button class="danger-button" :disabled="desk.busy" @click="safely(()=>removeSelected(form.action))">确认移出 {{desk.selection.length}} 项</button></footer></div>
  <form v-else-if="desk.dialog==='group'" @submit.prevent="safely(submit)"><label>内容名称<input v-model="form.title" placeholder="例如 光影与美化" required></label><label>说明<textarea v-model="form.description" rows="3" placeholder="告诉玩家，这组内容适合什么情况"></textarea></label><label class="check"><input v-model="form.defaultInstall" type="checkbox">默认安装</label><details v-if="form.id" class="advanced"><summary>内容 ID</summary><input :value="form.id" readonly></details><footer><button type="button" @click="close">取消</button><button class="accent">保存可选内容</button></footer></form>
  <form v-else-if="desk.dialog==='group-members'" @submit.prevent="safely(submit)"><p>将所选 {{desk.selection.length}} 项加入一组可选内容。</p><label>可选内容<select v-model="form.groupId" required><option value="" disabled>选择一组内容</option><option v-for="group in desk.project?.maintenance?.optionalGroups||[]" :key="group.id" :value="group.id">{{group.title}}</option></select></label><button type="button" class="text-action" @click="desk.dialog='group';desk.dialogData={}">新建可选内容</button><footer><button type="button" @click="close">取消</button><button class="accent" :disabled="!form.groupId">确认加入</button></footer></form>
  <div v-else-if="desk.dialog==='restore'"><p>确认以下变化后，再执行恢复。之后需要检查并发布，玩家才会收到。</p><div class="restore-changes"><article v-for="(change,i) in desk.operationPlan?.changes||[]" :key="i"><strong>{{change.path||change.setting||change.label||change.field||'设置变化'}}</strong><div><pre>{{change.before??change.current??'—'}}</pre><ChevronRight :size="16"/><pre>{{change.after??change.restored??'—'}}</pre></div></article><p v-if="!desk.operationPlan?.changes?.length">{{'当前设置已与发布版本一致。'}}</p></div><footer><button @click="close">取消</button><button class="accent" :disabled="desk.busy||!desk.operationPlan?.changes?.length" @click="safely(restoreConfirm)">确认恢复</button></footer></div>
  <form v-else-if="desk.dialog==='rollback'" @submit.prevent="safely(submit)"><p>使用 {{form.release?.displayVersion}} 的内容，创建一个新的发布版本。</p><label>新版本号<input v-model="form.version" required placeholder="例如 1.0.2"></label><label>回滚说明<textarea v-model="form.notes" rows="3"></textarea></label><label class="check"><input v-model="form.ack" type="checkbox">玩家使用 0.2.0 或更新的玩家端</label><footer><button type="button" @click="close">取消</button><button class="accent">创建回滚发布</button></footer></form>
  <div v-else-if="desk.dialog==='problem-confirm'"><div class="dialog-warning"><AlertTriangle :size="24"/><p>选择的 {{form.versions?.length}} 个历史坏版本，将在发布后要求玩家移出。即使之前已停止维护，也会处理匹配的副本。</p></div><label>问题说明<input v-model="form.reason" placeholder="例如 会导致客户端崩溃"></label><footer><button @click="close">取消</button><button class="danger-button" @click="safely(submit)">保存问题处理</button></footer></div>
  <div v-else-if="desk.dialog==='import-server'"><p>选择管理端所在电脑或服务器上的文件，先检查后导入。</p><button class="full" @click="openBrowse('file','import')"><FolderOpen :size="16"/>浏览服务器文件…</button></div>
  <form v-else-if="desk.dialog==='correct'" @submit.prevent="safely(submit)"><p>用标准目录中的 <strong>{{form.path}}</strong> 修复玩家副本。玩家原文件会先备份。</p><label>修复范围<select v-model="form.mode"><option value="ONCE">每个玩家修复一次</option><option value="KNOWN_BAD">只修复选中的历史坏版本</option></select></label><template v-if="form.mode==='KNOWN_BAD'"><label v-for="version in repairVersions" :key="version.sha256" class="history-version"><input v-model="form.badSha256" type="checkbox" :value="version.sha256"><span>{{version.version||version.sha256.slice(0,10)}}</span><small>{{version.firstRelease}} · {{bytes(version.size)}}</small></label></template><label>修复说明<input v-model="form.reason" required placeholder="例如 修复导致崩溃的配置"></label><footer><button type="button" @click="close">取消</button><button class="accent" :disabled="desk.busy||(form.mode==='KNOWN_BAD'&&!form.badSha256?.length)">保存修复要求</button></footer></form>
  <div v-else-if="desk.dialog==='browse'" class="server-browser"><div class="browse-toolbar"><button class="icon-button" aria-label="上一级服务器目录" :disabled="!desk.browse.parentPath&&!desk.browse.parent" @click="safely(()=>browse(desk.browse.parentPath||desk.browse.parent))"><ArrowUp :size="17"/></button><input v-model="desk.browsePath" aria-label="服务器路径" @keyup.enter="safely(()=>browse(desk.browsePath))"><button @click="safely(()=>browse(desk.browsePath))">转到</button></div><div class="browse-roots"><button v-for="root in desk.browse.roots||[]" :key="root.path||root" @click="safely(()=>browse(root.path||root))">{{root.label||root.path||root}}</button></div><div class="browse-entries"><button v-for="entry in desk.browse.entries||[]" :key="entry.path" :class="{selected:desk.browseSelected===entry.path}" @click="desk.browseSelected=entry.path" @dblclick="entry.directory?safely(()=>browse(entry.path)):desk.browseSelected=entry.path"><img :src="entry.directory?'/icons/folder.svg':'/icons/file.svg'" alt=""><span>{{entry.name}}</span><small>{{entry.directory?'文件夹':bytes(entry.size)}}</small><ChevronRight v-if="entry.directory" :size="14"/></button></div><footer><span>{{desk.browseSelected||desk.browsePath}}</span><button @click="close">取消</button><button class="accent" @click="safely(browseConfirm)">{{desk.browseAction==='import'?'暂存所选文件':'使用这个目录'}}</button></footer></div>
  <div v-else-if="desk.dialog==='service'"><div class="service-summary"><Server :size="28"/><div><strong>{{desk.state.publicService?.running?'下载服务运行中':'下载服务已停止'}}</strong><p>{{desk.state.publicService?.address||`${desk.state.settings?.httpHost}:${desk.state.settings?.httpPort}`}}</p></div></div><p>本机关闭窗口后，服务会继续在托盘中运行。</p><footer><button @click="safely(()=>service('stop'))"><Square :size="14"/>停止</button><button @click="safely(()=>service('restart'))"><RefreshCw :size="14"/>重启</button><button class="accent" @click="safely(()=>service('start'))"><Play :size="14"/>启动下载服务</button></footer></div>
  <div v-else-if="desk.dialog==='file-actions'" class="file-action-list"><button @click="desk.inspector=true;close">查看文件详情</button><button @click="desk.dialog='preset-confirm';desk.dialogData={preset:'SYNC'}">修改维护方式…</button><button @click="desk.dialog='group-members';desk.dialogData={}">加入可选内容…</button><button class="danger-text" @click="desk.dialog='remove'">移出所选内容…</button></div>
 </section></div>
</template>
